   foreach([1,2] as $slot){$old=new WC_Coupon(instapass_promo_config($slot)['coupon_id']);ip4_check(is_wp_error((new WC_Discounts(WC()->cart))->is_coupon_valid($old)),$cur.' old code rejected '.$slot.' qty '.$qty);}
  }
  WC()->cart->empty_cart();WC()->cart->add_to_cart(142);WC()->cart->add_to_cart(151);WC()->cart->calculate_totals();ip4_check(WC()->cart->apply_coupon($c['code']),$cur.' mixed tenors');WC()->cart->calculate_totals();$sum=$cur==='PKR'?47000+24400:168+87;ip4_check(abs((float)WC()->cart->get_total('edit')-round($sum*.95,2))<.011,$cur.' mixed total');
  foreach([31,32,55,144] as $id)ip4_check(!wc_get_product($id)->is_purchasable(),$cur.' other offer held '.$id);
 }
 $GLOBALS['ip_cc_test_currency']='EUR';$order=new WC_Order();instapass_cc_snapshot($order);ip4_check($order->get_currency()==='EUR'&&$order->get_meta('_instapass_currency_snapshot')['currency']==='EUR','Unsaved order EUR snapshot');
 $p=new WC_Product_Simple();$p->set_regular_price('10');ip4_check(instapass_cc_amount('10',$p,'price','EUR')==='','Missing EUR never falls back');$p->update_meta_data('_instapass_eur_regular_price','25');$p->update_meta_data('_instapass_eur_sale_price','20');ip4_check(instapass_cc_amount('10',$p,'price','EUR')==='20.00','Independent EUR sale');
