 $v=ip_offer_read(wc_get_product(30));$v['eur_regular']='22';$v['eur_sale']='';$v['eur_discount']='5';$parsed=ip_offer_values($v);ip4_check($parsed['eur_regular']==='22.00'&&$parsed['eur_sale']==='20.90','Owner EUR form validation');
 $GLOBALS['ip_cc_test_front']=false;wp_set_current_user((int)get_users(['role'=>'administrator','number'=>1,'fields'=>'ID'])[0]);
