 $request=new WP_REST_Request('POST','/');$request->set_header('content-type','application/json');$request->set_body(wp_json_encode(['mode'=>'import','currency'=>'EUR','rows'=>[['sku'=>wc_get_product(30)->get_sku(),'currency'=>'EUR','regular'=>'15','discount'=>'5','sale'=>'']]]));$preview=Instapass_Control_Bulk::preview($request);ip4_check(!is_wp_error($preview),'EUR spreadsheet preview');ip4_check($preview['changes'][0]['after']===['regular'=>'15.00','sale'=>'14.25'],'EUR preview amount');
 $apply=new WP_REST_Request('POST','/');$apply->set_param('token',$preview['token']);$result=Instapass_Control_Bulk::apply($apply);ip4_check(!is_wp_error($result)&&$result['state']==='applied','EUR batch applies');ip4_check(wc_get_product(30)->get_meta('_instapass_eur_sale_price')==='14.25','EUR batch persisted');$undone=Instapass_Control_Bulk::undo($apply);ip4_check(!is_wp_error($undone)&&$undone['state']==='undone','EUR batch undo');ip4_check(wc_get_product(30)->get_meta('_instapass_eur_sale_price')===''&&wc_get_product(30)->get_meta('_instapass_eur_regular_price')==='15.00','EUR exact restored');
 WC()->cart->empty_cart();$GLOBALS['ip_cc_test_front']=false;
}
